/**
 * Allows logging of data from the rasterization process, for display or debugging purposes
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
import '../../../globals.js';
import { alpenglow } from '../alpenglow.js';
export class RasterLog {
    constructor() {
        this.scale = null;
        this.partialAreas = [];
        this.fullAreas = [];
        this.tileLogs = [];
        this.renderableFaces = null;
    }
}
export class RasterTileLog {
    constructor() {
        this.translation = null;
        this.toIntegerMatrix = null;
        this.fromIntegerMatrix = null;
        this.integerEdges = null;
        this.filteredRationalHalfEdges = null;
        this.refilteredRationalHalfEdges = null;
        this.innerBoundaries = null;
        this.outerBoundaries = null;
        this.faces = null;
        this.unboundedFace = null;
        this.renderedFaces = null;
        this.initialRenderableFaces = null;
        this.renderableFaces = null;
        // How many integer intersections were detected
        this.integerIntersectionCount = 0;
        // How many times we ran the integer intersection computation
        this.integerIntersectionComputationCount = 0;
        // How many times we inspected bounds between two edges (or groups), to see if we should try intersecting them
        this.integerIntersectionOverlapCheckCount = 0;
    }
}
alpenglow.register('RasterLog', RasterLog);
